    static JSONObject parseObject(String text) { try { return new JSONObject(text); } catch (Exception e) { throw new IllegalArgumentException("Invalid hardcoded configuration", e); } }
    static JSONObject requireObject(JSONObject source, String key) { try { return source.getJSONObject(key); } catch (Exception e) { throw new IllegalArgumentException("Missing hardcoded config object: " + key, e); } }
    static String requireString(JSONObject source, String key) { try { return source.getString(key); } catch (Exception e) { throw new IllegalArgumentException("Missing hardcoded config string: " + key, e); } }
    static long requireLong(JSONObject source, String key) { try { return source.getLong(key); } catch (Exception e) { throw new IllegalArgumentException("Missing hardcoded config integer: " + key, e); } }

    static String readBundled(Context context) { return HARDCODED; }
    static String readEffective(Context context) { return HARDCODED; }
    static String listBundledSectionsJson(Context context) { return "[\"config.json\",\"anim.json\",\"home.json\",\"is_display.json\",\"jet_note_color_change_language.json\",\"media.json\",\"post_composer.json\",\"status_bar.json\",\"viewer.json\"]"; }
    static String readEffectiveSection(Context context, String section) {
        String name = normalize(section);
        switch (name) {
            case "config.json": return SECTION_0;
            case "anim.json": return SECTION_1;
            case "home.json": return SECTION_2;
            case "is_display.json": return SECTION_3;
            case "jet_note_color_change_language.json": return SECTION_4;
            case "media.json": return SECTION_5;
            case "post_composer.json": return SECTION_6;
            case "status_bar.json": return SECTION_7;
            case "viewer.json": return SECTION_8;
            default: throw new IllegalArgumentException("Unknown hardcoded config section: " + section);
        }
    }
    static String readOverrideSection(Context context, String section) { readEffectiveSection(context, section); return "{}"; }
    static boolean saveRuntime(Context context, String json) { return false; }
    static boolean saveRuntimeSection(Context context, String section, String json) { return false; }
    static boolean undoRuntime(Context context) { return false; }
    private static String normalize(String section) { String name = section == null ? "" : section.trim(); return name.endsWith(".json") ? name : name + ".json"; }
